	public Main() {
		FastScanner scanner = new FastScanner();
		java.io.PrintWriter writer = new java.io.PrintWriter(System.out);
		run(scanner, writer);
		writer.flush();
	}

	public void run(FastScanner scanner, java.io.PrintWriter writer) {
		int n = scanner.nextInt();
		long k = scanner.nextLong();
		final long[] factArr = new long[n + 1], invArr = new long[n + 1];
		final int MOD = 998244353;
		factArr[0] = 1;
		for (int i = 0; i < n; ++i) factArr[i + 1] = factArr[i] * (i + 1) % MOD;
		invArr[n] = IntMath.pow((int) factArr[n], MOD - 2, MOD);
		for (int i = n; i > 0; --i) invArr[i - 1] = invArr[i] * i % MOD;
		BiFunction<Integer, Integer, Long> comb = (i, j) -> factArr[i] * invArr[j] % MOD * invArr[i - j] % MOD;
		if (k == 0) {
			writer.println(factArr[n]);
		} else if (k > n) {
			writer.println(0);
		} else {
			int kIdx = (int) k;
			int rem = n - kIdx;
			long totalAns = 0;
			for (int i = 1; i <= rem; ++i) {
				long tmp = comb.apply(rem, i) * IntMath.pow(i, n, MOD) % MOD;
				totalAns += ((rem - i) & 1) != 0 ? -tmp : tmp;
			}
			totalAns = (totalAns % MOD + MOD) % MOD;
			totalAns = totalAns * 2 * comb.apply(n, kIdx) % MOD;
			writer.println(totalAns);
		}
	}

	static class FastScanner {
		private final java.io.InputStream inStream = System.in;
		private final byte[] buf = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) return true;
			ptr = 0;
			try {
				buflen = inStream.read(buf);
			} catch (java.io.IOException e) {
				e.printStackTrace();
			}
			return buflen > 0;
		}
		private byte readByte() {
			return hasNextByte() ? buf[ptr++] : -1;
		}
		private static boolean isPrintable(byte c) {
			return c > 32 || c < 0;
		}
		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}
		public boolean hasNext() {
			while (hasNextByte() && !isPrintable(buf[ptr])) ptr++;
			return hasNextByte();
		}
		public String next() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			byte b;
			while (isPrintable(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
