using namespace std;

long long pow_mod(long long base, long long exp, int mod) {
    long long result = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) result = result * cur % mod;
        cur = cur * cur % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    const int MOD = 998244353;
    std::vector<long long> factArr(n + 1, 1), invArr(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        factArr[i + 1] = factArr[i] * (i + 1) % MOD;
    }
    invArr[n] = pow_mod(factArr[n], MOD - 2, MOD);
    for (int i = n; i > 0; --i) {
        invArr[i - 1] = invArr[i] * i % MOD;
    }
    auto comb = [&](int i, int j) -> long long {
        if (j < 0 || j > i) return 0;
        return factArr[i] * invArr[j] % MOD * invArr[i - j] % MOD;
    };
    if (k == 0) {
        cout << factArr[n] << "\n";
    } else if (k > n) {
        cout << 0 << "\n";
    } else {
        int kIdx = (int)k;
        int rem = n - kIdx;
        long long totalAns = 0;
        for (int i = 1; i <= rem; ++i) {
            long long tmp = comb(rem, i) * pow_mod(i, n, MOD) % MOD;
            if (((rem - i) & 1) != 0) {
                totalAns -= tmp;
            } else {
                totalAns += tmp;
            }
        }
        totalAns = (totalAns % MOD + MOD) % MOD;
        totalAns = totalAns * 2 % MOD;
        totalAns = totalAns * comb(n, kIdx) % MOD;
        cout << totalAns << "\n";
    }
    return 0;
}
